import{_ as s,O as a,o as i,c as o,a as n,i as r,f as c}from"./chunks/framework.fmIt2z2h.js";const g=JSON.parse('{"title":"D.17　生产、交换、产权、制度与发展","description":"","frontmatter":{"title":"D.17　生产、交换、产权、制度与发展","xkChars":632,"xkLessons":{"D.17":{"title":"D.17　生产、交换、产权、制度与发展","lead":"经济统计把一项服务计入产出，不代表居民已经方便地使用，也不意味着质量充分。讨论发展与改革，要把价格、产权、工作、机会和实际分配保留下来，并说明究竟相对哪个基线作比较。","explanation":["原文定位：第4789—4804行；原文锚点 section-d-17；短引文：‘会计恒等不是因果机制，所有权名称不等实际控制，交易发生也不证明双方具有相称选择。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","古典政治经济学、马克思政治经济学、新古典福利分析、奥地利学派、制度经济学和发展研究，分别关注生产、价值、交换、知识、权力及历史变化。一般流动、承接等框架词不能替代价格、产权、劳动过程和制度规则。跨理论比较要保留各自专业变量与争论，不应先把经济学削成只有价格或现金的简单模型，再宣称新增几个字段即已补全。","市场价格可以协调分散信息与交换，但价格不独自说明福利、真实机会和权利分配。成交价可能反映支付能力与规则下的选择，不直接等于所有受影响者的价值；没有支付能力的人也可能有重要需要。承认价格在某任务中的作用，与保留价格以外的规范和分配问题可以同时成立。","会计恒等式说明按定义应怎样对账，不自动识别哪一因素造成另一因素。账面收入支出相等，不意味着提高某个账项必然带来某个现实结果；需要具体行为、约束和制度机制。所有权名称也不自动等于实际控制，实际控制要看谁能决定用途、取得收益、转让或阻止他人行动。","交易发生不证明双方具有相称选择。某人可能在缺乏替代、急迫需要或信息不足下成交；需要核可行选项、议价和风险，而不只看形式同意。比较不同制度应说明改变哪些通道、替代安排如何运行以及付出什么成本，不能只换市场、公有、合作或混合这些标签便宣布成效。","生产能力、人的实质能力和国家执行能力不是同一个能力变量。产线能生产更多，不说明个人能取得教育健康等真实机会；政府有名义项目，也不说明实际能执行到位。从资源到个人机会要经过资格、申请取得、服务质量及本人能否控制使用等条件。每一步可以有有限进步，也可能留下另一处障碍。","增长能支持教育、健康和选择，但发展还包含维护、照护、环境以及不能迁移者的位置。总体产出提高可能与某些地方负担增加并存。评价应保留路径中谁得益、谁承担转移成本、谁没有退出选择，不将全国或组织总量改进直接写成每个位置福利都提高。","非市场不等于不计入产出。国民核算对某些公共或非营利服务采用特定估值方法，计入的价值与服务是否易取得、质量是否充分是不同问题。应明确所用统计版本和价格或数量口径；不能把成本增加直接写成质量增加，也不能因为缺少市场售价就宣布服务没有核算价值。","无酬劳动不是零成本，执行者可能投入时间、精力和机会成本。合作社的会员也不必等于全部劳动者，所有者、雇员与被代表者范围须核。再分配则需区分法定资格、申请、实际领取和生活结果：资格扩大可能是真实进步，即使领取障碍仍在；领取提高也不能替代对生活效果的评价。","改革比较必须固定基线和过渡路径。最终相对最初无人受损，与最终相对中间状态有人受损，可以同时成立。不能为突出最终方案可行而删除中间改革曾经提供的机会，也不能用不同基线偷换某一方损失的有无。必要时同时报告多组差值，让读者知道各结论相对哪里。","静态可行安排不包办投资、可信承诺和后续产能。今天能分配的存量，不证明明天维护生产仍可持续；短期收益也不保证长期资源与执行条件。要分析具体动态链，而不是以现在可行或一个均衡存在结束制度比较。原有经济学中的权力、执行、分配和成本研究，应作为相称对照保留。","八个入口依次是Smith与Ricardo古典政治经济学，马克思政治经济学，新古典福利，Mises Hayek Rothbard奥地利传统，Coase Williamson North制度经济学，发展与结构转型，福利国家再分配社会保障，以及非市场合作社混合制度。最强反方认为承认实际机会会否认增长和价格的成果；回应是保留已经成立的统计或资源改善，同时要求它们不要冒充所有生活结果。"],"distinctions":[{"leftTitle":"会计恒等","leftText":"按口径必须相符的账项关系。","rightTitle":"因果机制","rightText":"行为约束制度如何造成变化须独立证据。"},{"leftTitle":"名义产权","leftText":"法律或组织上归属名称。","rightTitle":"实际控制","rightText":"决定使用收益处置与阻止他人的能力另核。"},{"leftTitle":"统计产出计入","leftText":"按特定核算方法赋值。","rightTitle":"居民机会与服务质量","rightText":"获取使用及质量不能由计入自动证明。"},{"leftTitle":"资格与领取","leftText":"有权申请和实际得到是不同阶段。","rightTitle":"生活结果","rightText":"得到资源后是否形成需要的改善另核。"},{"leftTitle":"最终对初始","leftText":"一组明确基线比较。","rightTitle":"最终对中间","rightText":"另一组路径比较，损益方向可能不同而不矛盾。"}],"boundaries":["不将价格或产出等同全部福利与权利，不取消其有限信息和核算价值。","统计恒等不当因果证明，无酬不当无成本。","不得由合作社会员身份推定所有劳动者都有同等决定权。","改革损益须明示基线与路径，不把静态可行当长期可持续。","数字服务和人群均教学构造；本讲不作真实政策投资或个案经济决策建议。"],"questions":["统计产出与实际可用机会为什么不同？","改革为何要同时交代初始与中间基线？","无酬劳动为何仍可能有成本？","静态可行为何不保证发展持续？"],"diagramPath":"/reading-assets/S-D-17/figures/section-d-17.png","caseLinks":[{"title":"真实统计方法：2008SNA中的非市场产出","href":"https://unstats.un.org/unsd/nationalaccount/docs/sna2008.pdf"}],"caseNotes":[{"title":"真实统计方法：2008SNA中的非市场产出","text":"2008版《国民账户体系》6.128定义非市场产出，6.130将免费提供给住户的相应产出按生产成本之和估值，列中间消耗、雇员报酬、固定资本消耗及其他生产税减补贴；6.131解释象征性收费为什么不能直接作为合适估值基础。它直接反驳非市场所以不计产出的概括，却不认证某项现实服务质量或可及性。","sourceLabel":"联合国等，System of National Accounts2008，Chapter6","sourceUrl":"https://unstats.un.org/unsd/nationalaccount/docs/sna2008.pdf","sourceLocator":"2008SNA印刷pp110—111，§6.128—6.132，尤其6.130四成本项与6.131；PDF168—169页","boundary":"这里固定2008版本，不称2026最新标准或各国现行全部方法；未核真实地区实施与服务结果，不把成本法用于所有非市场活动或全部无酬劳动。","href":"https://unstats.un.org/unsd/nationalaccount/docs/sna2008.pdf"}],"sourceRefs":[{"section":"D.17","start_line":4789,"end_line":4804,"startLine":4789,"endLine":4804}],"outputId":"section-d-17","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["保留价格产权劳动制度等专业变量，明确比较理论与相称对照。","分开核算定义、因果机制、名义所有与实际控制、交易发生与真实选择。","追踪资源经资格取得质量本人控制转成机会，保留生产个人国家三种能力。","区分非市场估值、服务使用与质量，无酬劳动和非会员劳动者不隐去。","固定基线与过渡路径，静态与动态分开，逐位置保留实际改善和剩余损失。"],"teachingExamples":[{"title":"原文教学例展开：成本计产出，使用仍困难","text":"假想某公共服务按所采用核算规则以成本估值并计入产出，但居民因资格证明复杂、距离远或服务质量不足而难以实际使用。计入产出可以成立，机会不足也可成立；既不能说非市场所以不计，也不能说已计所以质量充分。","assumptions":"服务与障碍为教学设定，具体核算规则需查相应版本。","boundary":"不虚构真实地区统计，也不将统计计入视为成本全部有益。"},{"title":"数学教学构造：换基线改变损益判断","text":"设两人初始资源(5,5)，中间改革(8,8)，最终(7,9)。最终对初始差值(2,4)，无人资源减少；最终对中间差值(−1,1)，第一人减少1。两句话可同时真，必须保留过渡基线。","assumptions":"资源可比单位为构造，不是两人全部福利或正当性的尺度。","boundary":"不由无人资源减少直接推出所有权利与生活结果都改善。"},{"title":"教学构造：资格扩大但领取未到","text":"假想某项服务把资格从一类人扩展到另一类人，新增群体知道消息却仍受申请材料障碍而未领取。可以承认资格规则改善，但实际领取和生活结果未证；若后来申请简化，也须继续核服务到达。","assumptions":"无真实资格或个人资料。","boundary":"不判具体行政合法性，不由未领取否定规则变化存在。"},{"title":"教学构造：合作社会员不等全体劳动者","text":"假想合作社有10名会员并另外雇用4名非会员。会员投票真实发生，但不能说14名劳动者都有同等会员表决权；非会员的劳动保护和代表问题另需规则材料。","assumptions":"人数与安排全为教学构造，不影射真实合作社。","boundary":"不认为合作社必然如此，也不由成员投票就判整体公平。"}],"counterexamples":[{"identity":"source_counterexample","text":"没有市场售价的公共服务从来不计入产出。","effect":"须查核算体系，非市场产出可以按特定方法估值。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"最终比最初无人受损，所以相对中间状态也无人受损。","effect":"路径基线不同，(5,5)→(8,8)→(7,9)是反例。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"加入机会和权力字段即可补全只懂现金的全部经济学。","effect":"相称对照须保留已有权力执行分配成本研究，不能先削弱对方。","sourceIds":["theory"]}],"questionAnswers":[{"question":"统计产出与实际可用机会为什么不同？","answer":"估值规则与个人资格取得质量控制是不同环节，前者不能补齐后者。","basis":"本节原文及上述公开推导"},{"question":"改革为何要同时交代初始与中间基线？","answer":"不同基线的损益判断可相反，同时成立，省略会误导。","basis":"本节原文及上述公开推导"},{"question":"无酬劳动为何仍可能有成本？","answer":"投入者承担时间精力和机会成本，未付货币不等这些投入不存在。","basis":"本节原文及上述公开推导"},{"question":"静态可行为何不保证发展持续？","answer":"投资维护可信承诺和后续产能涉及跨期条件，需另外分析。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-17/figures/section-d-17.png","alt":"价格产权劳动制度，保留专业变量，不压成一般流动；会计恒等≠因果，所有名称≠实际控制，成交≠选择相称；资源到机会，资格取得质量，本人实际控制；非市场可计产出，计入不证明质量，无酬不等零成本；改革基线先固定，初始／中间／最终，不同损益可并存；静态安排外还要核，投资维护与承诺，各位置后果保留。作者依D.17绘制；改革资源与合作社人数为教学构造，不是政策实证。","caption":"作者依D.17绘制；改革资源与合作社人数为教学构造，不是政策实证。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换基线、领取与质量环节和产权控制差异，显示哪种结论被实际材料支持。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"固定版本原始统计标准说明非市场产出估值，统计定义与生活质量严格分开。"},"openQuestions":["未取得17.01—17.08全部原研究，未做真实制度改革评估。","只核2008SNA指定段，不主张其为最新版本，未核各国现行实施及真实服务质量。"],"taskId":"S-D-17","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4789—4804行；每节精确范围见sourceRefs","claim_support":["D.17：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"sna2008","title":"System of National Accounts2008 — Chapter6","url":"https://unstats.un.org/unsd/nationalaccount/docs/sna2008.pdf","source_type":"primary","version_or_date":"2008版本","locator":"印刷pp110—111，§6.128—6.132，尤其6.130与6.131；PDF168—169","claim_support":["非市场产出定义、特定免费服务成本估值及象征性收费处理"],"limits":["固定2008版非最新性声明；不涵盖所有无酬活动，不认证现实实施可及性或质量。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-17/lecture.md","sourcesPath":"/reading-assets/S-D-17/sources.json","sourceSlicePath":"/reading-assets/S-D-17/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-17/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-17.md","filePath":"theory/appendix-d/d-17.md"}'),d={name:"theory/appendix-d/d-17.md"};function l(u,e,p,h,m,f){const t=a("SectionLesson");return i(),o("div",null,[e[0]||(e[0]=n('<div class="theory-source"><h1 id="section-d-17" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.17</span><span class="xk-num__gap">　</span></span>生产、交换、产权、制度与发展 <a class="header-anchor" href="#section-d-17" aria-label="Permalink to &quot;D.17　生产、交换、产权、制度与发展 {#section-d-17}&quot;">​</a></h1><p>正文连接：§2.8；§10.6.1；§12.10；§14.4；§15.3.5。研究入口：17.01—17.08。</p><p>古典政治经济学、马克思政治经济学、新古典福利分析、奥地利学派、制度经济学与发展研究，分别提出生产、价值、交换、知识、权力和历史变化的问题。框架保留其专业变量与争论，不用一般“流动”“承接”抹去价格、产权、劳动过程和制度规则。</p><p>市场价格可以组织分散信息与交换，却不独自说明福利、真实机会或权利分配。会计恒等不是因果机制，所有权名称不等实际控制，交易发生也不证明双方具有相称选择。比较制度时应检查规则改变哪些具体通道、替代方案怎样运行及其成本，而不是只换抽象标签。</p><p>生产能力、人的实质能力与国家执行能力不同。经济增长可以支持教育、健康和选择，但从资源到实际可用机会还要经过资格、取得、质量和本人控制。发展路径也包含维护、照护、环境与无法迁移者，不能以总体产出替代各位置后果。</p><p>教学例：一种公共服务在统计上按成本计入产出，居民实际使用却仍困难；它不是“非市场所以不计入”，也不是“已计入所以质量充分”。无酬劳动不是零成本，合作社会员也不等所有劳动者。再分配应追踪法定资格、申请、实际领取和生活结果，保留每一步的真实改善与剩余缺口。</p><p>比较改革必须固定基线与过渡路径。最终状态相对最初状态无人受损，与最终状态相对中间改革状态有人受损可以同时成立；静态可行安排也不包办投资、可信承诺与后续产能。相称的经济学对照应保留原有权力、执行、分配和成本研究，不能先把它削成仅有价格或现金，再以新增字段宣称补全。</p><p>专题定位：17.01 古典政治经济学：Smith、Ricardo；17.02 马克思政治经济学；17.03 新古典经济学与福利分析；17.04 奥地利学派：Mises、Hayek、Rothbard；17.05 制度经济学：Coase、Williamson、North；17.06 发展经济学与结构转型；17.07 福利国家、再分配与社会保障；17.08 非市场经济、合作社与混合制度。</p></div>',1)),r(t,{section:"D.17"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const x=s(d,[["render",l]]);export{g as __pageData,x as default};
